  async function getEmailBody(item) {
    return new Promise((resolve, reject) => {
        item.body.getAsync(Office.CoercionType.Text, (asyncResult) => {
            if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
                resolve(asyncResult.value); // 正文内容
            } else {
                reject(asyncResult.error); // 错误信息
            }
        });
    });
}

  async function getToEmails(item) {
    return new Promise((resolve, reject) => {
        item.to.getAsync((asyncResult) => {
            if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
                resolve(asyncResult.value.map((recipient) => recipient.emailAddress).join(","));
            } else {
                reject(asyncResult.error);
            }
        });
    });
}

async function getFromEmail(item) {
  return new Promise((resolve, reject) => {
    if (!item.from || typeof item.from.getAsync !== "function") {
      resolve({
        displayName: "",
        emailAddress: ""
      });
      return;
    }

    item.from.getAsync((asyncResult) => {
      if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
        const value = asyncResult.value;

        resolve({
          displayName: value?.displayName || "",
          emailAddress: value?.emailAddress || ""
        });
      } else {
        reject(asyncResult.error);
      }
    });
  });
}

  function generateGuid() {
    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return window.crypto.randomUUID();
    }
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
      const r = (Math.random() * 16) | 0;
      const v = c === "x" ? r : (r & 0x3) | 0x8;
      return v.toString(16);
    });
  }

// 获取新建邮件的主题
const getSubject = (item) => {
  return new Promise((resolve, reject) => {

    if (!item) {
      resolve("");
      return;
    }

    // 读取邮件标题
    if (item.subject && typeof item.subject.getAsync === "function") {
      item.subject.getAsync((result) => {

        if (result.status === Office.AsyncResultStatus.Succeeded) {
          console.log("📧 当前邮件标题:", result.value);
          resolve(result.value || "");
        } else {
          console.error("获取邮件标题失败:", result.error);
          reject(result.error);
        }

      });

      return;
    }

    // 某些 Outlook 场景 subject 可能直接可读
    if (typeof item.subject === "string") {
      console.log("📧 当前邮件标题:", item.subject);
      resolve(item.subject);
      return;
    }

    resolve("");
  });
};
async function getCcEmails(item) {
  return new Promise((resolve, reject) => {
    item.cc.getAsync((asyncResult) => {
      if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
        const recipients = asyncResult.value || [];

        resolve(
          recipients
            .map(recipient => recipient.emailAddress)
            .filter(Boolean)
            .join(",")
        );
      } else {
        reject(asyncResult.error);
      }
    });
  });
}

// 保存 CustomProperties
const saveCustomProperties = (item, key, value) => {
  return new Promise((resolve, reject) => {

    // 必须先加载当前邮件的 CustomProperties
    item.loadCustomPropertiesAsync((result) => {

      if (result.status !== Office.AsyncResultStatus.Succeeded) {
        reject(result.error);
        return;
      }

      // 这里拿到的就是“当前 Outlook 邮件”的 CustomProperties
      const customProps = result.value;

      console.log("CustomProperties 加载成功");
      console.log("当前邮件 CustomProperties:", customProps);

      // 设置属性
      customProps.set(key, value);

      // 保存到当前邮件
      customProps.saveAsync((saveResult) => {

        if (saveResult.status === Office.AsyncResultStatus.Succeeded) {
          console.log(
            "CustomProperties 保存成功:",
            key,
            value
          );

          resolve();
        } else {
          reject(saveResult.error);
        }

      });
    });
  });
};

const getCorrIdFromCurrentMail = async () => {
  try {
    const item = Office.context.mailbox.item;

    if (!item) {
      throw new Error("当前没有邮件 Item");
    }

    // 加载当前这封已发送邮件的 CustomProperties
    const customProps = await new Promise((resolve, reject) => {
      item.loadCustomPropertiesAsync((result) => {
        if (result.status === Office.AsyncResultStatus.Succeeded) {
          resolve(result.value);
        } else {
          reject(result.error);
        }
      });
    });

    // 读取之前保存的数据
    const value = customProps.get("tempRestUser");

    console.log("当前已发送邮件 tempRestUser:", value);

    if (!value) {
      console.log("当前邮件没有找到 tempRestUser");
      return null;
    }

    // 解析之前保存的 JSON
    const data = JSON.parse(value);

    console.log("当前已发送邮件绑定数据:", data);
    console.log("当前已发送邮件 corrId:", data.corrId);

    return data.corrId;

  } catch (error) {
    console.error("读取当前邮件 corrId 失败:", error);
    return null;
  }
};


const setCorrelationHeader = (item, corrId) => {
  return new Promise((resolve, reject) => {

    if (
      !item.internetHeaders ||
      typeof item.internetHeaders.setAsync !== "function"
    ) {
      reject(
        new Error(
          "当前 Outlook 环境不支持 internetHeaders.setAsync"
        )
      );
      return;
    }

    console.log("========== 开始设置 Header ==========");
    console.log("corrId =", corrId);

    item.internetHeaders.setAsync(
      {
        "x-msp-correlation-id": corrId
      },
      (result) => {

        console.log("setAsync result =", result);

        if (result.status !== Office.AsyncResultStatus.Succeeded) {

          console.error(
            "❌ Header 设置失败:",
            result.error
          );

          reject(result.error);
          return;
        }

        console.log(
          "✅ Header setAsync 成功"
        );

        // 立即读取
        item.internetHeaders.getAsync(
          ["x-msp-correlation-id"],
          (getResult) => {

            console.log(
              "getAsync result =",
              getResult
            );

            if (
              getResult.status !==
              Office.AsyncResultStatus.Succeeded
            ) {

              console.error(
                "❌ Header 读取失败:",
                getResult.error
              );

              reject(getResult.error);
              return;
            }

            console.log(
              "📌 当前邮件 Header =",
              getResult.value
            );

            const headerValue =
              getResult.value?.["x-msp-correlation-id"];

            if (headerValue) {

              console.log(
                "🎉 Header 验证成功:",
                headerValue
              );

              resolve();

            } else {

              console.error(
                "❌ Header 不存在"
              );

              reject(
                new Error("Header 不存在")
              );
            }
          }
        );
      }
    );
  });
};

