// 同步
const handleSync = async () => {
  try { 
    console.log(1);
    setSyncStatus("同步中...");

    const item = Office.context.mailbox.item;

    if (!item) {
      throw new Error("当前没有可用的邮件对象");
    }

    // 1. 生成 Correlation ID
    const corrId = generateGuid();

    // 2. 获取主题
    const subject = await getSubject(item);


    // 3. 获取发件人
    const fromEmail = await getFromEmail(item);

    // 显示在页面
    setSenderInfo(fromEmail);

    // 4. 获取收件人
    const toEmail = await getToEmails(item);

    // 5. 获取抄送
    const ccEmail = await getCcEmails(item);


    // 5. 获取正文
    const emailBody = await getEmailBody(item);

    // 6. 组装业务数据
    const payloadObject = {
      subject: subject || "",
      from: fromEmail.emailAddress || "",
      to: toEmail || "",
      cc: ccEmail || "",
      content: (emailBody || "").replace(/[\r\n]/g, " "),
      corrId
    };

    const payload = JSON.stringify(payloadObject);

    console.log("同步邮件信息：", payloadObject);

    // 7. 保存 CustomProperties
    await saveCustomProperties(
      item,
      "tempRestUser",
      payload
    );

    console.log("CustomProperties 保存成功");

    // // 8. 写入 Internet Header
    await setCorrelationHeader(
      item,
      corrId
    );

    console.log(
      "X-MSP-Correlation-ID 写入成功:",
      corrId
    );

    // // 9. 全部成功
     setSyncStatus("同步成功");

  } catch (error) {
    console.error("邮件同步失败:", error);

    setSyncStatus("同步失败");
  }
};



